/* Single source of truth for the browser, Node models and Python collector. */
const fs = require("node:fs");
const path = require("node:path");
const root = path.resolve(__dirname, "..");
function output(config) {
  return (
    "/* Generated by scripts/build-config.cjs; edit tracker.config.json. */\n" +
    "(function(root){const config=" +
    JSON.stringify(config) +
    ';if(typeof module!=="undefined"&&module.exports)module.exports=config;else root.TrackerConfig=config;})(globalThis);\n'
  );
}
if (require.main === module) {
  const value = output(
    JSON.parse(fs.readFileSync(path.join(root, "tracker.config.json"))),
  );
  const target = path.join(root, "dist/config.js");
  if (process.argv.includes("--check")) {
    if (!fs.existsSync(target) || fs.readFileSync(target, "utf8") !== value)
      throw new Error("Run node scripts/build-config.cjs");
  } else fs.writeFileSync(target, value);
}
module.exports = { output };
